from collections import defaultdict

def fit_novelty_table(text, window):
    seen, repeats = defaultdict(int), defaultdict(int)
    for i in range(2, len(text) - 1):
        ctx = text[i - 2:i]                      # the previous two bytes
        recent = text[max(0, i - window):i]
        seen[ctx] += 1
        repeats[ctx] += text[i:i + 2] in recent  # does what follows repeat?
    return {c: 1 - repeats[c] / seen[c] for c in seen}

